package br.com.luvi.financaspessoais.lancamento.repository; import br.com.luvi.financaspessoais.lancamento.entity.Lancamento; import br.com.luvi.financaspessoais.lancamento.enums.TipoLancamento; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; public interface LancamentoRepository extends JpaRepository<Lancamento,Long>{ List<Lancamento> findByContaIdInAndDataBetweenOrderByDataDescDataHoraCadastroDescIdDesc(Collection<Long> ids,LocalDate i,LocalDate f); @Query("select coalesce(sum(l.valor),0) from Lancamento l where l.conta.id in :ids and l.tipo=:tipo and l.data<:data") BigDecimal somarAntesDe(@Param("ids")Collection<Long> ids,@Param("tipo")TipoLancamento tipo,@Param("data")LocalDate data); @Query("select coalesce(sum(l.valor),0) from Lancamento l where l.conta.id in :ids and l.tipo=:tipo and l.data between :inicio and :fim") BigDecimal somarNoPeriodo(@Param("ids")Collection<Long> ids,@Param("tipo")TipoLancamento tipo,@Param("inicio")LocalDate i,@Param("fim")LocalDate f); List<Lancamento> findByContaIsNull(); boolean existsByContaId(Long contaId); boolean existsByCategoriaId(Long categoriaId); }